module single_bit_cdc_synchronizer #(
   parameter NUM_STAGES = 3 // minimum 2 stages, recommended 3 stages
                            // probability of metastability decreases
                            // exponentially with #stages
) (
   input clk, //latch clock
   input d_in,
   output q_out;
);

