module SPI_AD(
	input SPI_CLK,
	input New_Word,
	input [12:0] Addr,
	input [7:0] Data,
	output reg [7:0] q,
	input RW,           //1 Write; 0 :read
	output reg SPI_CS,
	inout  reg SPI_Data,
	output reg Over
);

    reg [15:0] CMD;
    reg [7:0] Wr_Data;
    reg [7:0] SPI_Counter;
	always @(negedge SPI_CLK or posedge New_Word ) begin
		if(New_Word) begin
			CMD <={RW,1'b0,1'b0,Addr[12:0]};
			Wr_Data <=  Data;
			SPI_Counter <= 8'd0;
			Over   <= 1'b0;
			SPI_CS <= 1'b1;
			SPI_Data <= 1'b0;

		end
		else begin
			if(SPI_Counter <8'd16) begin             // first CMD 
				SPI_Counter <= SPI_Counter + 1'b1;
				SPI_Data <= CMD[15];
				CMD <= CMD <<1;
				SPI_CS <= 1'b0;
				q <= 8'd00;
			end	
			else if(SPI_Counter <8'd24) begin        //Data
				SPI_Counter <= SPI_Counter + 1'b1;
				if(RW) begin
					q <= {q[6:0],SPI_Data};
					SPI_Data <= 1'bz;
				end
				else begin
					SPI_Data <= Wr_Data[7];
					Wr_Data <= Wr_Data <<1;
				end
				SPI_CS <= 1'b0;
			end

			else if(SPI_Counter <8'd25) begin        //Data
				SPI_Counter <= SPI_Counter + 1'b1;
				if(RW) begin
					q <= {q[6:0],SPI_Data};
					SPI_Data <= 1'bz;
				end
				SPI_CS <= 1'b1;
			end
			else if(SPI_Counter <8'd32) begin	   // interval
				SPI_Counter <= SPI_Counter + 1'b1;
				SPI_CS <= 1'b1;
				SPI_Data <= 1'bz;
				Over   <= 1'b1;
			end		
			else begin
				SPI_Data <= 1'bz;
				SPI_CS <= 1'b1;
				Over   <= 1'b1;

			end
		end
	end








endmodule

module pdp1_alu(al_op, al_a, al_b, al_r, al_ovfl, al_w);
   parameter pdp_model = "PDP-1D";

   input [0:4] al_op;
   input [0:17] al_a;
   input [0:17] al_b;
   output reg [0:17] al_r;
   output reg 	     al_ovfl;
   output reg 	     al_w;

   wire [0:17] w_add_opa;
   wire [0:17] w_add_opb;

   assign w_add_opa = (al_op == `PDP1_OP_ISP | 
		       al_op == `PDP1_OP_IDX) ? 18'h1 : al_a;
   assign w_add_opb = (al_op == `PDP1_OP_SUB) ? ~al_b : al_b;

   wire [0:17] w_add_immed1;
   wire [0:17] w_add_result;
   wire [0:17] w_add_normalized;
   wire        w_add_ovfl;

   assign {w_add_ovfl, w_add_immed1} = w_add_opa + w_add_opb;
   assign w_add_result = (w_add_ovfl) ? (w_add_immed1) + 1 : w_add_immed1;
   assign w_add_normalized = (&w_add_result) ? 18'h0 : w_add_result;

   always @(al_op or al_a or al_b or w_add_result or 
	    w_add_normalized or w_add_ovfl) begin
      al_w = 1'b1;
      case(al_op)
	`PDP1_OP_ADD,
	`PDP1_OP_SUB:
	  begin
             al_r <= w_add_normalized;
	     al_ovfl <= (~w_add_opa[0] ^ w_add_opb[0]) & 
			(w_add_opa[0] ^ w_add_result[0]);
	  end
	`PDP1_OP_ISP,
	`PDP1_OP_IDX:
	  begin
	    al_r <= w_add_normalized;
            al_ovfl <= 0;
	  end
	`PDP1_OP_AND:
	  al_r <= al_a & al_b;
	`PDP1_OP_XOR:
	  al_r <= al_a ^ al_b;
	`PDP1_OP_IOR:
	  al_r <= al_a | al_b;
	default:
	  {al_ovfl, al_r, al_w} <= 0;
      endcase // case (al_op)
   end
endmodule

