                dispense  = 1'b1;
                change_5k = 1'b0;
                balance   = 5'd15;
            end
            S_CHANGE: begin
                dispense  = 1'b1;
                change_5k = 1'b1;
                balance   = 5'd20;
            end
            default: begin
                dispense  = 1'b0;
                change_5k = 1'b0;
                balance   = 5'd0;
            end
        endcase
    end

