        .change_5k(change_5k),
        .balance(balance),
        .state_out(state_out)
    );

    always #10 clk = ~clk;

    task insert_5k;
        begin
            @(posedge clk);
            coin_5k = 1'b1;
            @(posedge clk);
            coin_5k = 1'b0;
        end
    endtask

    task insert_10k;
        begin
            @(posedge clk);
            coin_10k = 1'b1;
            @(posedge clk);
            coin_10k = 1'b0;
        end
    endtask

    initial begin
